import{_ as t,c as a,o as r,a3 as s}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Personnalisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/customize.md","filePath":"fr/guide/customize.md","lastUpdated":1787284674000}'),i={name:"fr/guide/customize.md"};function o(n,e,l,u,d,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="personnalisation" tabindex="-1">Personnalisation <a class="header-anchor" href="#personnalisation" aria-label="Permalink to &quot;Personnalisation&quot;">​</a></h1><p>Faites fonctionner ClipboxAI à votre façon. Ce guide couvre les réglages que vous pouvez ajuster.</p><h2 id="general" tabindex="-1">Général <a class="header-anchor" href="#general" aria-label="Permalink to &quot;Général&quot;">​</a></h2><p>Ouvrez <strong>ClipboxAI → Réglages</strong> (ou appuyez sur <code>Cmd+,</code>).</p><ul><li><strong>Langue</strong> : anglais, 简体中文, 繁體中文, 日本語.</li><li><strong>Lancement à la connexion</strong> : démarrer l&#39;application automatiquement à la connexion.</li><li><strong>Apparence</strong> : Clair, Foncé ou Système (suit macOS).</li></ul><h2 id="configuration-de-l-ia" tabindex="-1">Configuration de l&#39;IA <a class="header-anchor" href="#configuration-de-l-ia" aria-label="Permalink to &quot;Configuration de l&#39;IA&quot;">​</a></h2><p>Configurez l&#39;IA cloud dans <strong>Réglages → IA</strong> :</p><table tabindex="0"><thead><tr><th>Réglage</th><th>Options</th><th>Description</th></tr></thead><tbody><tr><td><strong>Fournisseur</strong></td><td>DeepSeek, MiniMax, GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic, Gemini</td><td>Le service compatible OpenAI à appeler</td></tr><tr><td><strong>Clé API</strong></td><td>votre clé</td><td>Stockée dans le <strong>Keychain</strong>, jamais écrite en texte clair sur le disque</td></tr><tr><td><strong>Modèle</strong></td><td>par fournisseur</td><td>Le modèle utilisé pour les actions IA</td></tr><tr><td><strong>IA cloud activée</strong></td><td>Activé / Désactivé</td><td>Interrupteur principal pour l&#39;envoi d&#39;éléments vers le cloud</td></tr></tbody></table><p>L&#39;IA cloud est <strong>désactivée par défaut</strong>. Lorsqu&#39;elle est activée, votre élément n&#39;est envoyé qu&#39;au fournisseur que vous avez configuré.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p>Personnalisez le comportement des outils :</p><ul><li><strong>Exécuter automatiquement à la sortie</strong> : lorsqu&#39;il est activé, l&#39;outil sélectionné s&#39;exécute automatiquement dès que vous copiez.</li><li><strong>Applications exclues</strong> : les applications listées ici sont ignorées par la surveillance du presse-papiers et l&#39;exécution automatique (ex. gestionnaires de mots de passe).</li><li><strong>Ordre des outils</strong> : dans la fenêtre Outil IA, glissez les outils installés pour les réorganiser ; votre ordre est mémorisé.</li></ul><h2 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to &quot;Confidentialité&quot;">​</a></h2><p>Ouvrez <strong>Réglages → Confidentialité</strong> :</p><ul><li><strong>Option d&#39;IA cloud</strong> : l&#39;interrupteur principal pour l&#39;envoi de données à un fournisseur.</li><li><strong>Applications exclues</strong> : empêcher certaines applications d&#39;être capturées.</li><li><strong>Contrôles de l&#39;historique</strong> : gérer la durée de conservation des éléments sur votre appareil.</li></ul><p>Tout l&#39;historique reste local. Nous ne téléversons pas les éléments ni ne faisons d&#39;analytique.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>Gérez les actions installées :</p><ul><li><strong>Parcourir</strong> : ouvrez le <strong>Marketplace</strong> depuis la fenêtre Outil IA ou le site.</li><li><strong>Installer</strong> : cliquez sur <strong>Installer</strong> sur une action pour l&#39;ajouter via un lien profond.</li><li><strong>Supprimer</strong> : désinstallez une action de votre liste <strong>Installés</strong>.</li></ul><h2 id="barre-de-menus" tabindex="-1">Barre de menus <a class="header-anchor" href="#barre-de-menus" aria-label="Permalink to &quot;Barre de menus&quot;">​</a></h2><ul><li><strong>Afficher dans la barre de menus</strong> : activer/désactiver l&#39;icône de menu.</li><li><strong>Quitter à la fermeture</strong> : choisissez si l&#39;application reste en cours d&#39;exécution en arrière-plan.</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li>Gardez l&#39;IA cloud désactivée jusqu&#39;à ce que vous en ayez besoin — les outils locaux couvrent la plupart du nettoyage quotidien.</li><li>Ajoutez les gestionnaires de mots de passe et les applications de saisie sécurisée aux <strong>Applications exclues</strong> afin que les secrets ne soient jamais capturés.</li><li>Associez l&#39;exécution automatique à un outil local pour un nettoyage de texte mains libres à chaque copie.</li></ul>',23)])])}const m=t(i,[["render",o]]);export{g as __pageData,m as default};
